// One learner goal (canDo) and 4+ specific sub-goals per B1 lesson, shared by all three sheets
// (docs/LESSON_QUALITY_CONTRACT.md A1–A3, owner 2026-10-12). Lessons 1–50 come from their reviewed Avasta sheets,
// 51–75 were rewritten from the generic course defaults. Block goal ids (g_vocab, g_read, g_notice, g_use) stay.
export const B1_LESSON_GOALS = {
  "a2b1-001": {"canDo":"Ma näitan, mida oskan igapäevaelu teemal juba iseseisvalt kasutada.","goals":{"g_vocab":"Õpilane kasutab igapäevaelu põhisõnu (päev, töö, pere, kodu) ilma sõnastikuta.","g_read":"Õpilane vastab lühikese igapäevateksti 6 küsimusele, sh üks põhjus.","g_notice":"Õpilane moodustab oleviku vormid (ma töötan, ta töötab) ja eitused.","g_use":"Õpilane räägib endast ja oma päevast 1 minuti jooksul."}},
  "a2b1-002": {"canDo":"Ma räägin oma tavalisest päevast 1,5–2 minutit ja kasutan vähemalt viit ajamarkerit.","goals":{"g_vocab":"Õpilane kasutab päevarutiini tegusõnu ja kellaaegu: ärkan, lähen tööle, kell pool kaheksa.","g_read":"Õpilane järjestab tekstist inimese päeva tegevused ja kellaajad.","g_notice":"Õpilane märkab ajamarkereid hommikul, enne, pärast, siis ja nende kohta lauses.","g_use":"Õpilane räägib oma päevast 1,5–2 minutit vähemalt viie ajamarkeriga."}},
  "a2b1-003": {"canDo":"Ma kasutan sagedussõnu ja hoian lihtlauses loomuliku sõnajärje.","goals":{"g_vocab":"Õpilane kasutab sagedussõnu: alati, tavaliselt, sageli, mõnikord, harva, mitte kunagi.","g_read":"Õpilane leiab tekstist, kui tihti inimesed midagi teevad.","g_notice":"Õpilane hoiab tegusõna teisel kohal: Tavaliselt joon ma kohvi.","g_use":"Õpilane räägib oma harjumustest kuue lausega, igas üks sagedussõna."}},
  "a2b1-004": {"canDo":"Ma räägin oma nädalast 6–8 seotud lausega ja võrdlen tööpäeva nädalavahetusega.","goals":{"g_vocab":"Õpilane kasutab nädalapäevi ja vormi esmaspäeval, nädalavahetusel, tööpäeval.","g_read":"Õpilane võrdleb tekstist tööpäeva ja nädalavahetust.","g_notice":"Õpilane märkab vormi -l päevade juures: esmaspäeval, laupäeval.","g_use":"Õpilane räägib oma nädalast 6–8 seotud lausega ja võrdleb kahte päeva."}},
  "a2b1-005": {"canDo": "Ma kirjeldan oma igapäevaelu iseseisvalt ning kasutan aega, sagedust ja olevikku piisavalt täpselt.", "goals": {"g_read": "Õpilane vastab igapäevateksti küsimustele vähemalt 70% ulatuses.", "g_notice": "Õpilane kasutab õigesti olevikku, ajamarkereid ja sõnajärge.", "g_use": "Õpilane kirjeldab oma igapäevaelu suuliselt ja kirjalikult."}},
  "a2b1-006": {"canDo":"Ma tutvustan 4–5 lähedast inimest ja ütlen igaühe kohta ühe detaili.","goals":{"g_vocab":"Õpilane kasutab pere ja sugulaste sõnu: sugulane, onu, tädi, nõbu, vanavanemad, lapselaps, abikaasa.","g_read":"Õpilane mõistab Sofia fotojuttu, Mia kirjandit ja Helgi kutset kokkutulekule ning ütleb, kes kellele on.","g_notice":"Õpilane moodustab omastava küsimusele kelle? (venna, õe, Jaani) ja kirjeldab sugulust: minu ema vend = onu.","g_use":"Õpilane tutvustab end kokkutulekul kaugele sugulasele ja kirjutab Helgile kutsele 70–90-sõnalise vastuse."}},
  "a2b1-007": {"canDo":"Ma kirjeldan inimese välimust ja iseloomu vähemalt 8 seotud lausega.","goals":{"g_vocab":"Õpilane kasutab välimuse ja iseloomu sõnu: habe, prillid, lokkis, rahulik, täpne, tagasihoidlik, abivalmis.","g_read":"Õpilane mõistab Sofia kirja uutest kolleegidest, teadet kadunud lapsest ja Kadri lapsehoidja kuulutust.","g_notice":"Õpilane kirjeldab inimest kes-kõrvallausega (kes, kellel, keda, kellega) ja paneb kõrvallause ette koma.","g_use":"Õpilane valib paarilisega lastele lapsehoidja, põhjendab valikut rühmale ja kirjutab valitud kandidaadile kirja."}},
  "a2b1-008": {"canDo":"Ma küsin ja vastan, kelle asi see on, ning kasutan omastavat ja sõna „oma” õigesti.","goals":{"g_vocab":"Õpilane kasutab kaotamise sõnu: kaotama, leidma, unustama, maha jätma, nimesilt, omanik, kadunud.","g_read":"Õpilane mõistab pikniku järel vestlust, pargi teadet ja maja grupi postitusi: mis kadus, milline see on, kelle oma.","g_notice":"Õpilane eristab oma ja tema (Oskar jättis oma jope maha) ning kirjeldab asja mis-lausega: kott, mille kaotasin.","g_use":"Õpilane salvestab häälsõnumi kaotatud või leitud asjast ja kirjutab maja grupile postituse, kuidas omanik asja tagasi saab."}},
  "a2b1-009": {"canDo":"Ma räägin, mida me lähedastega koos teeme, teen ettepaneku ja põhjendan oma eelistust.","goals":{"g_vocab":"Õpilane kasutab otsustamise sõnu: ettepanek, eelistama, kokku leppima, kokkulepe, traditsioon, hääletama, rahul.","g_read":"Õpilane mõistab Liisi blogist, pere arutelust ja Jaani kirjast, kes mida eelistab ja mis on veel otsustamata.","g_notice":"Õpilane teeb ettepaneku (Lähme…!, Võiksime…), põhjendab sest- või kuna-lausega ja sõnastab kokkuleppe: Lepime kokku, et…","g_use":"Õpilane lepib pere nõupidamisel kokku Helgi üllatuspeo plaani ja kirjutab sugulastele 9–11-lauselise kutse."}},
  "a2b1-010": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti omastavat, sõna „oma” ja „ta on / tal on”.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-011": {"canDo":"Ma kirjeldan oma tuba 6–8 seotud lausega ja ütlen, kus mis asub.","goals":{"g_vocab":"Õpilane kasutab korteri sõnu: üür, omanik, valgusküllane, ruumikas, ebamugav, lärmakas, kodune, tugitool.","g_read":"Õpilane mõistab Sofia sõnumist, kolmest üürikuulutusest ja omaniku vastusest, milline korter on ja kas see sobib.","g_notice":"Õpilane moodustab omadussõnu liidetega -ne, -line, -kas, -lik, -tu ja eba-: kivine, päikeseline, ruumikas, ebamugav.","g_use":"Õpilane valib paarilisega Kalamaja või Pelgulinna korteri, helistab omanikule ja kirjutab talle kirja kahe küsimusega."}},
  "a2b1-012": {"canDo":"Ma valin õige küsimuse ja kohavormi ning ütlen, kus ma olen, kuhu lähen ja kust tulen.","goals":{"g_vocab":"Õpilane kasutab kolimise sõnu: kolima, kast, viima, tooma, panema, perenaine, postkast, trepikoda.","g_read":"Õpilane mõistab Sofia häälsõnumist, Markuse sõnumitest ja maja reeglitest, mida kust võtta ja kuhu viia.","g_notice":"Õpilane eristab kus? kuhu? kust? ja moodustab vormirea: autos – autosse – autost, riiulil – riiulile – riiulilt.","g_use":"Õpilane juhendab telefonis kolimist, jätab Sofiale häälsõnumi ja kirjutab 9–11 lauset, kust asjad võeti ja kuhu viidi."}},
  "a2b1-013": {"canDo":"Ma nimetan vähemalt 12 linnakohta, ütlen, mida seal tehakse, ja soovitan tuttavale, kuhu minna.","goals":{"g_vocab":"Õpilane kasutab linnakohtade sõnu: apteek, raamatukogu, tervisekeskus, perearst, turg, spordikeskus, pakiautomaat, linnaosa.","g_read":"Õpilane mõistab linnaosa meelespead, ringkäiku Kalamajas ja Helgi kirja: kus mis asub ja mida seal teha.","g_notice":"Õpilane moodustab linnakohtade kuhu-, kus- ja kust-vormid: apteeki, raamatukokku, turule; apteegis, turul; pangast.","g_use":"Õpilane rahustab telefonis ema, tutvustab giidina oma linnaosa ja kirjutab Helgile, miks Kalamaja on ohutu."}},
  "a2b1-014": {"canDo":"Ma küsin teed viisakalt ja annan vähemalt nelja järjestatud juhise abil arusaadava teekirjelduse.","goals":{"g_vocab":"Õpilane kasutab teejuhatuse sõnu: otse, paremale, vasakule, pöörama, ületama, ristmik, valgusfoor, sissepääs.","g_read":"Õpilane mõistab Anna teejuhatust, tervisekeskuse kodulehte ning Helgi ja Viktori häälsõnumeid ja leiab kaardilt tee.","g_notice":"Õpilane moodustab käsu sõbrale ja võõrale (pööra – pöörake, ära mine – ärge minge) ning -ni vormi: kuni ristmikuni.","g_use":"Õpilane juhatab telefonis Helgi jaamast uude koju ja kirjutab soolaleivapeo kutse koos teekirjeldusega."}},
  "a2b1-015": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli 3 kodu, linna ja tee sõnu ilma toeta.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti kus-, kuhu- ja kust-vorme ning käsku.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-016": {"canDo":"Ma kirjeldan oma päevaplaani ja kasutan vähemalt kuut ajamarkerit.","goals":{"g_vocab":"Õpilane kasutab aja sõnu: kõigepealt, enne, pärast, lõpuks, kestma, veerand, hilinema, avatud, umbes.","g_read":"Õpilane mõistab pere esmaspäeva hommikut, Sofia kirja töönädalast ja laagrijuhi kirja: mis toimub millal ja kui kaua.","g_notice":"Õpilane ütleb kellaaja (veerand, pool, kolmveerand), kestuse (kella üheksast kella viieni) ja enne/pärast + osastav: pärast kooli.","g_use":"Õpilane koostab keelelaagri päevakava, tutvustab seda vanematele 1,5–2 minutit ja kirjutab lapsevanematele kirja."}},
  "a2b1-017": {"canDo":"Ma valin peab, võib, saab või ei tohi vastavalt olukorrale ja selgitan reegleid.","goals":{"g_vocab":"Õpilane kasutab reeglite sõnu: reegel, kohustus, keelatud, lubatud, ei tohi, luba, parkima, vaikus.","g_read":"Õpilane mõistab lao reegleid, lasteaia häälsõnumit ja maja vanema kõnet: mis on kohustus, luba või keeld.","g_notice":"Õpilane kasutab peab / ei pea + ma-vormi ning võib, saab, ei tohi, mul on vaja + da-vormi.","g_use":"Õpilane lepib maja koosolekul kokku kolm reeglit, põhjendab neid sõnavõtus ja kirjutab maja gruppi 9–11 lauset."}},
  "a2b1-018": {"canDo":"Ma selgitan vähemalt viit kohustust ja kahte prioriteeti ning põhjendan, miks need on tähtsad.","goals":{"g_vocab":"Õpilane kasutab ühendverbe ja kohustuse sõnu: läbi lugema, ette valmistama, ära maksma, edasi lükkama, tähtaeg, kiire.","g_read":"Õpilane mõistab Markuse kõnet, Sofia sõnumit ja Anna ülesannete nimekirja: mida tuleb teha ja mis võib oodata.","g_notice":"Õpilane paneb ühendverbi osakese õigesse kohta: Ma loen aruande läbi; Ma pean aruande läbi lugema; Ma ei lükka seda edasi.","g_use":"Õpilane täpsustab telefonis Anna nimekirja, annab Liisile suulise aruande ja kirjutab Annale, mis tehti ja mis lükati edasi."}},
  "a2b1-019": {"canDo":"Ma viin läbi kolm lühikest kokkuleppedialoogi, kus pakun aega, keeldun vajadusel ja pakun alternatiivi.","goals":{"g_vocab":"Õpilane kasutab kokkuleppe sõnu: kokku leppima, sobima, muutma, kalender, vaba, kahjuks, ümber tegema, kinnitama.","g_read":"Õpilane mõistab Jaani telefoni teateid ja Sofia kõnet hambakliinikusse: mis aeg muutus ja mis on uus aeg.","g_notice":"Õpilane kasutab mustrit ettepanek → keeldumine + põhjus → muutmine → kokkulepe: Kas sulle sobib…? Kahjuks ei sobi… Lepime kokku…","g_use":"Õpilane teeb paarilisega sassi läinud nädalavahetusele uue plaani, räägib selle Kadrile ja kirjutab pere gruppi."}},
  "a2b1-020": {"canDo":"Ma sooritan vahehindamise Harno A2 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti moodulite 1–4 vorme: kohavormid, omastav, ajamarkerid, modaalverbid.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-021": {"canDo":"Ma moodustan sagedaste tegusõnade lihtmineviku vorme ja jutustan oma eilsest päevast.","goals":{"g_vocab":"Õpilane kasutab igapäevaseid tegusõnu minevikus: töötasin, helistasin, vastasin, lõpetasin, kohtusin, ostsin, ärkasin.","g_read":"Õpilane mõistab Markuse kõnest, Anna vastusest ja Liisi kirjadest, mida keegi eile või haige nädala jooksul tegi.","g_notice":"Õpilane moodustab lihtmineviku kõigis isikutes (töötasin, ta töötas, ostsin) ja eituse: ei töötanud, ei ostnud.","g_use":"Õpilane räägib haigeks jäänud Liisile häälsõnumis ja kohvipausil nädala uudistest ning kirjutab talle pika sõnumi."}},
  "a2b1-022": {"canDo":"Ma jutustan 8–10 lausega eilsest või eelmisest nädalast ja kasutan vähemalt nelja ajamarkerit.","goals":{"g_vocab":"Õpilane kasutab mineviku ajamarkereid: üleeile, eelmisel nädalal, möödunud suvel, … tagasi, kõigepealt, pärast seda, lõpuks.","g_read":"Õpilane mõistab Anna postitust, Sofia ja Viktori häälsõnumeid ning perearsti infolehte: mis juhtus mis järjekorras.","g_notice":"Õpilane alustab lauset ajamarkeriga ja paneb tegusõna teisele kohale: Laupäeval koristasin ma korteri.","g_use":"Õpilane kirjeldab arsti vastuvõtul, millal haigus algas ja mis edasi juhtus, ning kirjutab ülemusele 9–11-lauselise sõnumi."}},
  "a2b1-023": {"canDo":"Ma kasutan vähemalt 8 sagedast erandlikku lihtmineviku vormi õigesti ja kirjeldan üht üritust.","goals":{"g_vocab":"Õpilane kasutab festivali sõnu ja erandvorme: festival, vabatahtlik, müüja, tuli, läks, tegi, nägi, sõi, jõi, sai.","g_read":"Õpilane mõistab raadioreportaaži, Jaani päevikut, Viktori kirja ja lehe arvustust: kes festivalil mida tegi.","g_notice":"Õpilane moodustab erandlikud mineviku vormid (tuli, tegi, sõi, jõi, tõi, viis, läks) ja eituse: ei tulnud, ei läinud.","g_use":"Õpilane annab festivalist raadiointervjuu, kutsub sõbra järgmisele festivalile ja kirjutab festivali kodulehele kommentaari."}},
  "a2b1-024": {"canDo":"Ma jutustan 2–3 minutit järjestatud sündmustest ja kasutan lihtminevikku ning vähemalt nelja siduvat ajamarkerit.","goals":{"g_vocab":"Õpilane kasutab loo sõnu: alguses, äkki, märkama, kaduma, otsima, ehmuma, mures, rõõmus, tagasi andma.","g_read":"Õpilane leiab Anna, Sofia ja Viktori loost alguse, probleemi, tegevuse, lõpu ja tunde muutumise.","g_notice":"Õpilane ehitab loo järjekorrasõnadega (alguses, äkki, kõigepealt, pärast seda, lõpuks) ja paneb tegusõna teisele kohale.","g_use":"Õpilane jutustab rühmale 2 minutit oma ootamatust päevast ja kirjutab linnalehe võistlusele 80–100-sõnalise loo."}},
  "a2b1-025": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti lihtmineviku tavalisi ja erandlikke vorme ning eitust.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-026": {"canDo":"Ma nimetan vähemalt 15 toiduainet, kasutan koguseid osastavaga ja kirjutan ostunimekirja.","goals":{"g_vocab":"Õpilane kasutab toidu ja koguse sõnu: toiduaine, kogus, nimekiri, pakk, pudel, liiter, köögivili, puuvili, värske.","g_read":"Õpilane mõistab Liisi postitust, turuvestlust Viktori juures ja internetist leitud nõuandeid: mida ja kui palju osta.","g_notice":"Õpilane kasutab koguse ja arvu järel osastavat: liiter piima, kilo kartuleid, kolm tomatit, natuke juustu.","g_use":"Õpilane planeerib paarilisega lõuna kaheksale, tutvustab Helgile menüüd ja kirjutab Jaanile ostunimekirja vähemalt 6 kogusega."}},
  "a2b1-027": {"canDo":"Ma tellin kohvikus või restoranis viisakalt, küsin koostise kohta ja maksan.","goals":{"g_vocab":"Õpilane kasutab restorani sõnu: menüü, päevapraad, eelroog, pearoog, magustoit, ettekandja, arve, eraldi, soovitama.","g_read":"Õpilane mõistab tellimist kohvikus Kaneel, kohviku kodulehte, laua broneerimise kõnet ja restorani Aed menüüd.","g_notice":"Õpilane tellib ja palub viisakalt (Palun mulle…, Ma sooviksin…, Kas saaksime arve?) ning kasutab -ks vormi: supiks, joogiks.","g_use":"Õpilane broneerib telefonis laua kuuele, tellib kogu pere eest allergiaid arvestades ja kirjutab pere gruppi sõnumi."}},
  "a2b1-028": {"canDo":"Ma valin õige osastava vormi pärast kogust, eitust ja tegusõna ning räägin oma toiduharjumustest.","goals":{"g_vocab":"Õpilane kasutab köögi sõnu: retsept, õhtusöök, salat, kaste, valmis, kogu, maitsma, lõikama, nõud.","g_read":"Õpilane mõistab Sofia päevikut, köögivestlust, Viktori kirja ja Liisi kirja: mis on valmis ja mis veel pooleli.","g_notice":"Õpilane eristab osastavat ja täissihitist: söön leiba – sõin leiva ära, tegi salati valmis; eituses on alati osastav.","g_use":"Õpilane lepib köögikoosolekul kokku viis reeglit, kirjutab kontori köögi reeglid ja vabandab kolleegile ära söödud lõuna pärast."}},
  "a2b1-029": {"canDo":"Ma kirjeldan probleemi viisakalt ja ütlen selgelt, millist lahendust soovin.","goals":{"g_vocab":"Õpilane kasutab kaebuse sõnu: probleem, viga, vabandama, kaebus, lahendus, vahetama, allahindlus, hilinema, arvustus.","g_read":"Õpilane mõistab Markuse juttu, Helgi poevestlust, kohviku arvustusi ja tellimuse tingimusi: mis läks valesti ja mis on lahendus.","g_notice":"Õpilane kasutab nelja sammu: viisakas pöördumine, probleem (Ma tellisin…, aga sain…), palve (Kas te saaksite…?) ja tänu.","g_use":"Õpilane nõuab telefonis klienditeeninduselt lahendust ning kirjutab kullerile kaebuse ja 9–11-lauselise arvustuse."}},
  "a2b1-030": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli 6 toidu, koguse ja teeninduse sõnu ilma toeta.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti osastavat koguse ja eituse järel ning viisakaid palveid.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-031": {"canDo":"Ma kirjeldan vähemalt kuut sümptomit ning ütlen, mis valutab, mis mul on ja kuidas end tunnen.","goals":{"g_vocab":"Õpilane kasutab tervise sõnu: pea, kurk, kõrv, valutama, palavik, nohu, köha, haige, terve, muutuma.","g_read":"Õpilane mõistab Anna ja Sofia vestlust, Jaani sõnumit, terviseportaali artiklit ja firma juhendit haigele töötajale.","g_notice":"Õpilane eristab olekut ja muutust: olen haige – jäin haigeks, sai terveks, läks paremaks (omastav + -ks).","g_use":"Õpilane teatab telefonis ülemusele haigusest, räägib kohvipausil paranemisest ja kirjutab kolleegile, mida tema eest teha."}},
  "a2b1-032": {"canDo":"Ma broneerin aja, annan arstile põhiinfo ja vastan täpsustavatele küsimustele.","goals":{"g_vocab":"Õpilane kasutab arsti ja apteegi sõnu: apteeker, retsept, ravim, tablett, valuvaigisti, allergia, kestma, kukkuma, põlv.","g_read":"Õpilane mõistab ravimi infolehte, Viktori lugu põlvest ja kõnet nõuandeliinile 1220: mida teha ja kui tihti ravimit võtta.","g_notice":"Õpilane vastab küsimustele millal?, kui kaua?, kui tihti? ja mõistab teie-käsku: Võtke üks tablett! Ärge võtke piimaga!","g_use":"Õpilane kirjeldab nõuandeliinil 1220 probleemi, räägib Jaanile õe soovitustest ja kirjutab perearstile e-kirja."}},
  "a2b1-033": {"canDo":"Ma annan vähemalt viis sobivat nõuannet käskiva kõneviisiga ja mõistan tüüpilisi juhiseid.","goals":{"g_vocab":"Õpilane kasutab nõuannete sõnu: nõuanne, soovitama, juhis, käsk, keeld, puhkama, magama, uni, proovima.","g_read":"Õpilane mõistab Kadri sedelit, raadio terviserubriiki, füsioterapeudi juhiseid ja Anna saadetud une artiklit.","g_notice":"Õpilane moodustab käsu ja keelu sinale ja teile (too – ära too, andke – ärge andke) ning pehme nõuande: sa võiksid.","g_use":"Õpilane koostab Markusele uneplaani, annab raadios 1,5–2 minutit nõu ja kirjutab Markusele, mida teha ja mida mitte."}},
  "a2b1-034": {"canDo":"Ma kirjeldan vähemalt kolme harjumust, selgitan nende mõju ja ütlen, mida peaksin muutma.","goals":{"g_vocab":"Õpilane kasutab harjumuste sõnu: harjumus, tervislik, väljakutse, liikuma, magus, eesmärk, tulemus, jätkama.","g_read":"Õpilane mõistab Liisi väljakutse kirja, kohvipausi vestlust, harjumuste artiklit ja Liisi kokkuvõtet tulemustest.","g_notice":"Õpilane eristab pean (kohustus), peaksin (nõuanne) ja võiksin (võimalus) ning pöörab tingivat kõigis isikutes.","g_use":"Õpilane räägib 2 minutit oma 30 päeva väljakutsest ja annab uuele kolleegile Kristjanile suulist ja kirjalikku nõu."}},
  "a2b1-035": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti mul valutab / mul on, käsku ja peaksin / võiksin.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-036": {"canDo":"Ma räägin kaks minutit oma õppimispäevast ja kasutan vähemalt 12 teemasõna.","goals":{"g_vocab":"Õpilane kasutab kooli sõnu: õppeaine, tunniplaan, vahetund, kontrolltöö, klassijuhataja, huvituma, osalema, harjuma, valmistuma.","g_read":"Õpilane mõistab lastevanemate koosolekut, Oskari kirjandit „Minu kolmapäev”, Helgi nõuandeid ja Olena sõnumit.","g_notice":"Õpilane kasutab tegusõna rektsiooni: huvitub millest?, osaleb milles?, harjub millega?, valmistub milleks?, palub kellelt?","g_use":"Õpilane selgitab Olenale Eesti kooli, jätab talle häälsõnumi ja kirjutab Olena nimel klassijuhatajale kirja Dariast."}},
  "a2b1-037": {"canDo":"Ma valin pärast sagedasi tegusõnu õige vormi (pean õppima, tahan õppida) ja räägin oma õppimisplaanist.","goals":{"g_vocab":"Õpilane kasutab õppimise sõnu: eksam, eesmärk, plaan, harjutama, kordama, proovima, päevik, proovitest, puhkama.","g_read":"Õpilane mõistab Anna eksamiplaani, õpetaja kodutöö juhist ja Liisi kutset kontori õpiklubisse.","g_notice":"Õpilane valib pean, lähen, hakkan järel ma-vormi ning tahan, oskan, saan, proovin, meeldib, on raske järel da-vormi.","g_use":"Õpilane lepib kokku õpiklubi päeva ja reeglid, tutvustab oma klubitundi ja kirjutab infotahvlile teate."}},
  "a2b1-038": {"canDo":"Ma vastan küsimusele „miks?” täislausega ja kasutan sest, kuna ja sellepärast et õiges sõnajärjes.","goals":{"g_vocab":"Õpilane kasutab põhjuse sõnu: põhjus, tagajärg, sest, kuna, seepärast, sellepärast et, motivatsioon, väsinud.","g_read":"Õpilane mõistab kohvipausi vestlust, keelekooli küsitlust, koolijuhi häälsõnumit ja teiste õppijate tagasisidet.","g_notice":"Õpilane eristab põhjust ja tagajärge ning sõnajärge: Kuna tööl on kiire, saab Anna…; seepärast ununevad sõnad.","g_use":"Õpilane annab koolijuhile telefonis tagasisidet, valib rühmaga kolm muudatust ja kirjutab kaks plussi ja kaks soovi põhjustega."}},
  "a2b1-039": {"canDo":"Ma kirjeldan õppimisprobleemi, selle põhjust ja vähemalt üht lahendust ning palun viisakalt abi.","goals":{"g_vocab":"Õpilane kasutab õpimure sõnu: mure, lahendus, puudu jääma, maha jääma, järele jõudma, julgema, keskenduma, abi paluma.","g_read":"Õpilane leiab Natalja loost, õpetaja Tiina häälsõnumist ja Helgi kirjast mure, põhjuse ja lahenduse.","g_notice":"Õpilane kasutab mustrit mure + põhjus + lahendus + palve: Ma jäin maha, sest…; Ma võiksin…; Kas te saaksite…?","g_use":"Õpilane valib nõustajaga kursuse, põhjendab valikut 2 minutit ja kirjutab koolile avalduse."}},
  "a2b1-040": {"canDo":"Ma sooritan vahehindamise Harno A2 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti lihtminevikku, osastavat, ma- ja da-vormi ning sest- ja kuna-lauset.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-041": {"canDo":"Ma nimetan vähemalt 12 ametit ja kirjeldan, mida inimene tööl teeb, mille eest vastutab ja millega tegeleb.","goals":{"g_vocab":"Õpilane kasutab töö sõnu: amet, tööülesanne, vastutama, tegelema, hoolitsema, vahetus, juhataja, klient, töökoht.","g_read":"Õpilane mõistab Sofia kodutööd, Kadri raadiosaadet „Minu amet” ja Kadri karjääripäeva kõnet: kes mida tööl teeb.","g_notice":"Õpilane kasutab konstruktsioone töötab kokana (-na), vastutab kontori eest, hoolitseb patsientide eest, tegeleb dokumentidega.","g_use":"Õpilane räägib karjääripäeval lastele 1,5–2 minutit oma ametist, vastab küsimustele ja kirjutab plakatile 9–11 lauset."}},
  "a2b1-042": {"canDo":"Ma räägin 2–3 minutit oma tööpäevast ja varasemast töökogemusest ning kasutan olevikku ja lihtminevikku.","goals":{"g_vocab":"Õpilane kasutab tööpäeva sõnu: töökogemus, koosolek, kohtuma, teenindama, aruanne, tähtaeg, tellimus, kontrollima.","g_read":"Õpilane mõistab Sofia telefonikõnesid, Jaani lugu töökogemusest, Kadri häälsõnumit ja kolme kõneposti sõnumit.","g_notice":"Õpilane kasutab ma-tegevusnime vorme: läks sööma, on kohtumas, tuleb söömast, kiri jäi vastamata.","g_use":"Õpilane vastab kontoris kolleegide asemel kõnedele, räägib Liisile päevast ja kirjutab talle 10–12-lauselise kokkuvõtte."}},
  "a2b1-043": {"canDo":"Ma räägin oma töökohustustest ja oskustest ning valin tööfraasides ma- või da-vormi õigesti vähemalt 8 korral 10-st.","goals":{"g_vocab":"Õpilane kasutab töökuulutuse sõnu: kohustus, oskus, kandideerima, suhtlema, lahendama, võimalus, koolitus, tööaeg.","g_read":"Õpilane mõistab administraatori töökuulutust, Liisi ja Anna arutelu ning Liisi märkmeid Jelena esimeseks päevaks.","g_notice":"Õpilane valib pean, hakkan, jään järel ma-vormi ning oskan, julgen, tuleb, on vaja järel da-vormi.","g_use":"Õpilane tutvustab uuele kolleegile Jelenale tööd, räägib koosolekul tema esimesest nädalast ja kirjutab 10–12-lauselise meelespea."}},
  "a2b1-044": {"canDo":"Ma vastan 6–8 töövestluse küsimusele täislausetega, toon oma tugevuse kohta näite ja esitan ise vähemalt ühe küsimuse.","goals":{"g_vocab":"Õpilane kasutab töövestluse sõnu: kandidaat, kandideerimiskiri, tugevus, nõrkus, kogemus, meeskond, usaldusväärne, väljaõpe.","g_read":"Õpilane mõistab Anna töövestlust, Töötukassa nõuandeid, kõneposti kutset vestlusele ja Jaani kandideerimiskirja.","g_notice":"Õpilane ehitab vastuse mustriga väide + näide + seos ja küsib viisakalt teie-vormis: Kas ma tohin küsida…?","g_use":"Õpilane kirjutab ühele kolmest kuulutusest kandideerimiskirja, peab 4–5-minutilise proovivestluse ja annab kandidaadile tagasisidet."}},
  "a2b1-045": {"canDo":"Ma sooritan tööteemalise eksami Harno B1 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti -na-vormi, vastutab … eest, minevikku ning ma- ja da-vormi.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-046": {"canDo":"Ma mõistan sõiduinfot ja ostan pileti: väljumine, saabumine, hind, perroon, ümberistumine.","goals":{"g_vocab":"Õpilane kasutab sõidu sõnu: väljuma, saabuma, ümber istuma, otserong, perroon, vagun, istekoht, edasi-tagasi, sõiduplaan.","g_read":"Õpilane mõistab Helgi kutset, Sofia ja Jaani kõnet rongi valikust, raudtee KKK-d ja Sofia märkmeid Viktori teekonnast.","g_notice":"Õpilane kasutab sõiduinfos kohavorme ja -ga: väljub Balti jaamast, saabub Tartusse, Tapal istub ümber, sõidame rongiga.","g_use":"Õpilane selgitab Viktorile telefonis teekonda, jätab Helgile häälsõnumi ja kirjutab onule sõnumi aja, pileti ja ümberistumisega."}},
  "a2b1-047": {"canDo":"Ma kirjeldan 2–3 minutit reisiplaani, võrdlen kaht võimalust ja põhjendan vähemalt kaks otsust.","goals":{"g_vocab":"Õpilane kasutab reisi planeerimise sõnu: töölähetus, mess, eelarve, lend, broneerima, majutus, soodne, mugav, võrdlema.","g_read":"Õpilane mõistab Liisi kirja meeskonnale, reisiblogi ja Anna kõnet hotelli: kuupäevad, hinnad ja võimalused.","g_notice":"Õpilane võrdleb kesk- ja ülivõrdega (odavam kui, palju kiirem, kõige kiirem, soodsaim) ja põhjendab sest / seepärast.","g_use":"Õpilane kaitseb koosolekul reisiplaani, esitleb seda meeskonnale 2 minutit ja kirjutab Liisile plaani, hinna ja kaks põhjust."}},
  "a2b1-048": {"canDo":"Ma jutustan reisist järjekorras ja kasutan vähemalt 8–10 õiget lihtmineviku vormi.","goals":{"g_vocab":"Õpilane kasutab reisiseikluse sõnu: juba, ummik, infolett, järgmine, vaba koht, ootama, kurtma, tagasi maksma.","g_read":"Õpilane mõistab Oskari kirjandit, Markuse kõnet Riiast ja raadiosaadet „Teel juhtunud”: mis juhtus enne ja mis pärast.","g_notice":"Õpilane moodustab enneminevikku (oli läinud, olime oodanud, polnud ostnud) ja eristab seda lihtminevikust ja täisminevikust.","g_use":"Õpilane räägib otse-eetris oma reisiloo, valib rühmaga parima loo ja kirjutab saate kodulehele oma reisiloo."}},
  "a2b1-049": {"canDo":"Ma kirjeldan reisiprobleemi, küsin täpsustavat küsimust, küsin või pakun alternatiivi ja lepin kokku lahenduse.","goals":{"g_vocab":"Õpilane kasutab reisiprobleemi sõnu: pagas, kohver, lennujaam, reisija, tühistama, hilinema, hüvitis, alternatiiv.","g_read":"Õpilane mõistab vestlust bussijaama kassas, reisija õigusi lennufirma kodulehel ja lennufirma e-kirja Sofiale.","g_notice":"Õpilane kasutab mustrit probleem → küsimus → alternatiiv → kokkulepe: Kas on mõni teine võimalus? Lepime nii kokku.","g_use":"Õpilane lahendab telefonis kadunud kohvri probleemi, kirjutab lennufirmale kaebuse kuludega ja annab Liisile suulise aruande."}},
  "a2b1-050": {"canDo":"Ma sooritan reisiteemalise eksami Harno B1 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti kohavorme, keskvõrret, lihtminevikku ja viisakaid küsimusi.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-051": {"canDo":"Ma räägin müüjaga, küsin hinda, suurust ja soodustust ning täpsustan vähemalt kolm detaili.","goals":{"g_vocab":"Õpilane kasutab poe sõnu: hind, soodustus, garantii, kehtima, tšekk, müüja, kaardiga, sularahas, kokku.","g_read":"Õpilane mõistab telefonipoe pakkumist, Sofia vestlust müüjaga, Jaani kohvriostu ja spordipoe pakkumist.","g_notice":"Õpilane küsib hinda, soodustust ja varianti (Kas seda on ka suuruses M?) ning soovib viisakalt: Ma võtaksin…","g_use":"Õpilane ostab rollimängus Oskarile jalgpallisaapad, jätab Kadrile häälsõnumi ja kirjutab talle, mida ja miks ostis."}},
  "a2b1-052": {"canDo":"Ma moodustan vähemalt kuus õiget võrdlust (suurem, odavam, parem, kõige parem) ja põhjendan nendega oma valikut.","goals":{"g_vocab":"Õpilane kasutab autoostu sõnu: kasutatud, kuulutus, kütus, pagasiruum, proovisõit, otsustama, odavam, uuem, parem.","g_read":"Õpilane mõistab Jaani ja Kadri arutelu, kahte autokuulutust, Jaani kõnet müüjale ja tarbijaportaali nõuandeid.","g_notice":"Õpilane moodustab kesk- ja ülivõrde (odavam, väiksem, parem, rohkem, kõige parem) ja võrdleb: odavam kui Škoda = Škodast odavam.","g_use":"Õpilane kaupleb müüjaga, põhjendab perele vähemalt viie võrdlusega auto valikut ja kirjutab müüjale kinnituskirja."}},
  "a2b1-053": {"canDo":"Ma selgitan kauba probleemi 3–4 sammuga, ütlen oma soovi ja mõistan müüja vastust.","goals":{"g_vocab":"Õpilane kasutab tagastamise sõnu: tagastama, vahetama, katkine, parandama, remont, pakend, kehtiv, teenindaja.","g_read":"Õpilane mõistab poe Nutikas ja e-poe Lasteriie tagastamise tingimusi ning Sofia vestlust klienditeeninduses.","g_notice":"Õpilane kasutab kesksõnu nimisõna ees: ostetud kaup, makstud arve, avatud pakend, kehtiv garantii.","g_use":"Õpilane helistab e-poodi vale jope pärast, vastab tagasisideküsitlusele ja kirjutab e-poele kirja oma sooviga."}},
  "a2b1-054": {"canDo":"Ma selgitan 5–6-sammulist e-teenuse protsessi, kasutan juhendis käsku ja küsin vajalikke täpsustusi.","goals":{"g_vocab":"Õpilane kasutab e-teenuse sõnu: müügiportaal, sisse logima, vajutama, kinnitama, pangaülekanne, konto, makse, petis, turvaline.","g_read":"Õpilane mõistab Jaani telefonijuhiseid Viktorile, turvalisuse nõuandeid ja Viktori kõnet pangaga.","g_notice":"Õpilane moodustab juhendi käsu sinale ja teile (vali – valige, ära vajuta – ärge andke) ja kesksõna: parandatud ratas.","g_use":"Õpilane räägib poe juhatajaga garantiist, täidab e-teeninduses garantiinõude ja kirjutab poele 9–11-lauselise arvustuse."}},
  "a2b1-055": {"canDo":"Ma sooritan raha ja ostlemise eksami Harno B1 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli põhisõnu: hind, soodustus, tšekk, garantii, arve, viitenumber.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti hinna ja suuruse vorme, võrdlust, tagastamise mustreid ja käsku.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-056": {"canDo":"Ma kirjeldan ilma, mõistan ilmateadet ja ütlen, mida selle ilmaga teha ja selga panna.","goals":{"g_vocab":"Õpilane kasutab ilma sõnu: sajab, puhub, pilves, udu, äike, kraadi sooja/külma, libe.","g_read":"Õpilane leiab ilmateatest päeva, temperatuuri, sademed ja soovitused.","g_notice":"Õpilane kasutab ilma lauseid ilma alusta (sajab, puhub), kraade ja muutust (läheb soojemaks).","g_use":"Õpilane valib ilma järgi tegevuse, lepib sõpradega kokku ja kirjutab grupisõnumi."}},
  "a2b1-057": {"canDo":"Ma räägin loodusest ja tegevustest õues, kasutan kus-, kuhu- ja kust-vormi ning vähemalt 12 teemasõna.","goals":{"g_vocab":"Õpilane kasutab looduse sõnu: mets, raba, järv, rand, matkarada, laudtee, vaatetorn, lõke.","g_read":"Õpilane mõistab matkalugu, igaüheõiguse reegleid ja kahe looduskoha kirjeldust.","g_notice":"Õpilane valib õige kohavormi (metsa, metsas, metsast) ning kasutab tohib / ei tohi.","g_use":"Õpilane soovitab külalisele looduskoha, teeb päeva plaani ja kirjutab selle sõbrale."}},
  "a2b1-058": {"canDo":"Ma ühendan põhjuse ja tagajärje vähemalt viie-kuue lausepaariga (sest, sellepärast, seetõttu, … tõttu) ja panen tegusõna õigele kohale.","goals":{"g_vocab":"Õpilane kasutab sõnu põhjus, tagajärg, sest, sellepärast, seetõttu, … tõttu, torm, hoiatama.","g_read":"Õpilane leiab tormihoiatusest ja tormilugudest põhjused ja tagajärjed.","g_notice":"Õpilane paneb pärast sellepärast / seetõttu tegusõna teisele kohale ja eristab põhjust tagajärjest.","g_use":"Õpilane kirjutab uudiskirja 80–100-sõnalise tormiloo põhjuste ja tagajärgedega."}},
  "a2b1-059": {"canDo":"Ma ütlen oma arvamuse keskkonnasõbralike harjumuste kohta mudeliga arvamus + põhjus + näide.","goals":{"g_vocab":"Õpilane kasutab keskkonna sõnu: prügi, sorteerima, konteiner, pakend, kasutatud, riidest kott.","g_read":"Õpilane mõistab pere kogemust, kolme arvamust ja majaühistu teadet ning leiab argumendid.","g_notice":"Õpilane kasutab väljendeid minu arvates, ma arvan, et, mulle tundub, et, näiteks ja tegusõna teisel kohal.","g_use":"Õpilane ütleb koosolekul arvamuse ja kirjutab juhatusele 80–100-sõnalise põhjendatud kirja."}},
  "a2b1-060": {"canDo":"Ma sooritan vahehindamise Harno B1 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_vocab":"Õpilane kasutab moodulite 9–12 põhisõnu töö, reisi, raha ja looduse kohta.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab B1-vastuse mudelit: väide, põhjus, näide, kokkuvõte.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-061": {"canDo":"Ma palun abi, teen ettepaneku ja keeldun viisakalt nii, et suhe jääb heaks.","goals":{"g_vocab":"Õpilane kasutab palve, ettepaneku ja keeldumise väljendeid: kas sa saaksid, kuidas oleks, kahjuks, meeleldi.","g_read":"Õpilane mõistab sõnumivahetusest, kes palub, pakub ja keeldub ning miks.","g_notice":"Õpilane märkab hea keeldumise mustrit: kahjuks + põhjus + uus ettepanek.","g_use":"Õpilane lepib sõpradega kokku päeva plaani, arvestades nende piiranguid."}},
  "a2b1-062": {"canDo":"Ma kasutan tingivat kõneviisi (sooviksin, saaksite, oleks), et teeninduses viisakalt paluda ja probleemi lahendada.","goals":{"g_vocab":"Õpilane kasutab teeninduse väljendeid: broneerima, kinnitus, sooviksin, kas oleks võimalik.","g_read":"Õpilane mõistab telefonikõnest ja hotelli kirjast olulise info.","g_notice":"Õpilane moodustab tingiva kõneviisi: soovin → sooviksin, saate → saaksite, on → oleks.","g_use":"Õpilane lahendab hotelliga probleemi telefonis ja kirjutab viisaka e-kirja."}},
  "a2b1-063": {"canDo":"Ma kuulan teist poolt, selgitan rahulikult oma seisukohta ja jõuan kompromissini.","goals":{"g_vocab":"Õpilane kasutab kompromissi väljendeid: ma saan aru, aga…; minu jaoks on tähtis…; mis oleks, kui…","g_read":"Õpilane leiab naabrite kaartidelt ja koosolekult igaühe soovi ja põhjuse.","g_notice":"Õpilane märkab, kuidas teravat lauset pehmendada.","g_use":"Õpilane osaleb läbirääkimisel ja esitab rühma kompromissi."}},
  "a2b1-064": {"canDo":"Kui midagi läheb valesti või ma ei saa aru, küsin üle, ütlen teisiti, pakun alternatiivi ja jätkan vestlust.","goals":{"g_vocab":"Õpilane kasutab üleküsimise ja muutuste sõnu: korrata, kas te mõtlete, jääb ära, hilineb, hoopis.","g_read":"Õpilane mõistab loost, teadaandest ja häälsõnumist, mis muutus.","g_notice":"Õpilane märkab, kuidas kontrollida, kas sai õigesti aru, ja öelda sama mõte teisiti.","g_use":"Õpilane reageerib ootamatusele, pakub plaani B ja jätkab vestlust."}},
  "a2b1-065": {"canDo":"Ma sooritan mooduli eksami Harno B1 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli 13 suhtlusväljendeid ilma toeta.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti tingiva kõneviisi ja viisakuse vorme.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-066": {"canDo":"Ma jutustan 3 minutit mineviku sündmusest selges järjekorras ja lisan aja, koha, inimesed ja tunde.","goals":{"g_vocab":"Õpilane kasutab jutustamise sõnu: eelmisel …, järsku, viimasel hetkel, hiljem, lõpuks, pettunud.","g_read":"Õpilane mõistab pikemaid minevikulugusid ning leiab aja, koha, sündmused ja tunde.","g_notice":"Õpilane kasutab lihtminevikku kõigis isikutes ja teeb lühikesest lausest detailse.","g_use":"Õpilane jutustab raadiointervjuus oma loo ja kirjutab 80–100-sõnalise loo."}},
  "a2b1-067": {"canDo":"Ma eristan elukogemust (olen käinud) ja konkreetset sündmust (käisin eile) ning küsin „Kas sa oled kunagi…?”.","goals":{"g_vocab":"Õpilane kasutab kogemuse sõnu: kunagi, mitte kunagi, juba, veel ei, kogemus.","g_read":"Õpilane mõistab intervjuud, küsimustikku ja ankeeti ning eristab kogemust ja sündmust.","g_notice":"Õpilane moodustab täismineviku (olen + -nud) ja valib täis- või lihtmineviku aja järgi.","g_use":"Õpilane vastab ankeedile 80–100 sõnaga ja räägib vestlusel oma kogemustest."}},
  "a2b1-068": {"canDo":"Ma seon sündmused jutustuseks, kasutan vähemalt seitset eri sidesõna ja panen pärast neid tegusõna teisele kohale.","goals":{"g_vocab":"Õpilane kasutab ajajoone sõnu: alguses, kõigepealt, seejärel, samal ajal, enne, hiljem, lõpuks.","g_read":"Õpilane leiab lugudest sündmuste järjekorra ja paneb need ajajoonele.","g_notice":"Õpilane paneb pärast ajajoone sõna tegusõna teisele kohale.","g_use":"Õpilane kirjutab albumisse 80–100-sõnalise ajajoonega loo ja esitleb seda."}},
  "a2b1-069": {"canDo":"Ma jutustan meeldejäävast kogemusest neljas osas: sündmus, tunne, põhjus ja järeldus.","goals":{"g_vocab":"Õpilane kasutab tundesõnu: närvis, hirmul, uhke, üllatunud, pettunud, tänulik.","g_read":"Õpilane leiab lugudest sündmuse, tunde, põhjuse ja järelduse.","g_notice":"Õpilane kasutab loos lihtminevikku ja järelduses täisminevikku (olen õppinud).","g_use":"Õpilane kirjutab võistlusele 100–120-sõnalise loo ja jutustab selle raadios."}},
  "a2b1-070": {"canDo":"Ma sooritan mineviku ja kogemuste eksami Harno B1 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli põhisõnu: ajajoone sõnad, kogemuse sõnad ja tunded.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane valib õigesti lihtmineviku ja täismineviku ning seob loo ajajoone sõnadega.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-071": {"canDo":"Ma räägin tulevikust loomulike eesti konstruktsioonidega: olevik + ajasõna ja hakkama + ma-vorm.","goals":{"g_vocab":"Õpilane kasutab tuleviku ajasõnu: homme, ülehomme, järgmisel nädalal, varsti, tulevikus.","g_read":"Õpilane leiab kalendrist, muutuste loost ja sõbra kirjast plaanid ja nende aja.","g_notice":"Õpilane väljendab tulevikku olevikuga ja hakkama + ma-vormiga, mitte saama/olema + ma-vormiga.","g_use":"Õpilane teeb külalisele kolme päeva programmi ja kirjutab selle 80–100 sõnaga."}},
  "a2b1-072": {"canDo":"Ma kirjeldan kolme eesmärki, põhjendan neid ja nimetan iga eesmärgi juurde kaks sammu.","goals":{"g_vocab":"Õpilane kasutab sõnu eesmärk, soovima, plaanima, lootma, selleks, samm, saavutama.","g_read":"Õpilane leiab tekstidest eesmärgid, põhjused ja sammud.","g_notice":"Õpilane kasutab da-vormi pärast soovin, plaanin, eesmärk on ning lauset loodan, et….","g_use":"Õpilane kirjutab stipendiumi taotluse 100–120 sõnaga ja räägib komisjonile oma plaanist."}},
  "a2b1-073": {"canDo":"Ma moodustan õigesti vähemalt kuus reaalset tingimuslauset (kui + olevik, (siis) …) ja teen plaani A ja B.","goals":{"g_vocab":"Õpilane kasutab tingimuse sõnu kui, siis, plaan B, mis siis, kui.","g_read":"Õpilane mõistab plaane ja reegleid, milles on kui-laused.","g_notice":"Õpilane kasutab kui-osas olevikku ja paneb pärast kui-osa tegusõna kohe.","g_use":"Õpilane kirjutab lapsele kui-lausetega meelespea ja räägib oma plaanist B."}},
  "a2b1-074": {"canDo":"Ma põhjendan oma plaani mudeliga otsus + kaks põhjust + näide + kokkuvõte.","goals":{"g_vocab":"Õpilane kasutab sõnu otsus, valima, esiteks, teiseks, näiteks, sellepärast, kokkuvõte.","g_read":"Õpilane leiab tekstidest otsuse, põhjused, näite ja kompromissi.","g_notice":"Õpilane kasutab põhjenduse mudelit ja keskvõrret (odavam, mugavam) ning tegusõna teisel kohal.","g_use":"Õpilane esitab juhatajale põhjendatud kaugtöö plaani suuliselt ja 80–100 sõnaga kirjalikult."}},
  "a2b1-075": {"canDo":"Ma sooritan tuleviku ja plaanide eksami Harno B1 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli põhisõnu: tuleviku ajasõnad, eesmärgi sõnad ja põhjendamise sõnad.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti tulevikku, da-vormi, kui-lauseid ja põhjenduse mudelit.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-076": {"canDo":"Ma avaldan igapäevastel teemadel arvamust täislausega ja annan vähemalt viis vastust kujul arvamus + põhjus.","goals":{"g_vocab":"Õpilane kasutab arvamuse väljendeid kindluse järgi: ma olen kindel, minu arvates, mulle tundub, ma ei arva.","g_read":"Õpilane leiab foorumist ja küsitlusest, kes mida arvab ja millise põhjusega.","g_notice":"Õpilane märkab, et pärast „minu arvates” tuleb kohe tegusõna ning „ma arvan / mulle tundub” järel et-lause.","g_use":"Õpilane annab vähemalt viis suulist vastust kujul arvamus + põhjus ja kirjutab linnaosale arvamuskirja."}},
  "a2b1-077": {"canDo":"Ma võrdlen kahte võimalust nelja võrdlusega (keskvõrre + kui, võrreldes + -ga, samas) ja põhjendan oma valikut.","goals":{"g_vocab":"Õpilane kasutab võrdlemise sõnu: odavam, mugavam, parem, halvem, eelis, puudus, samas.","g_read":"Õpilane leiab tekstist ja kuulutustest kahe võimaluse erinevused ning täidab võrdlustabeli.","g_notice":"Õpilane moodustab keskvõrde ja kasutab mustreid „… kui + nimetav” ning „võrreldes + -ga”.","g_use":"Õpilane võrdleb kaht võimalust nelja võrdlusega ja põhjendab oma valikut suuliselt ja kirjas."}},
  "a2b1-078": {"canDo":"Ma ehitan kolm lühikest argumenti skeemi järgi: arvamus → põhjus → näide → järeldus, suuliselt ja lõiguna.","goals":{"g_vocab":"Õpilane kasutab argumendi sõnu: kuna, näiteks, seetõttu, seega, esiteks, teiseks.","g_read":"Õpilane leiab lugejakirjast ja arvamusloost arvamuse, põhjuse, näite ja järelduse.","g_notice":"Õpilane märkab sõnajärge pärast „seetõttu / seega” ning kasutab des-vormi ja umbisikulist vormi üldises näites.","g_use":"Õpilane ehitab kolm argumenti skeemi arvamus → põhjus → näide → järeldus suuliselt ja lõiguna."}},
  "a2b1-079": {"canDo":"Ma osalen 4–5-minutilises arutelus: nõustun, vaidlen osaliselt vastu, toon näite ja esitan vastuküsimuse.","goals":{"g_vocab":"Õpilane kasutab arutelu väljendeid: olen nõus, ma ei ole päris nõus, jah, aga…, kuidas sina arvad?","g_read":"Õpilane mõistab arutelu tekstist ja kuulamisest, kes nõustub, kes vaidleb vastu ja milleni jõutakse.","g_notice":"Õpilane kasutab kaudset kõnet (ütles, et… / küsis, kas…), tingivat kõneviisi ja rektsiooni „nõus kellega, nõustuma millega”.","g_use":"Õpilane peab 4–5-minutilist arutelu, reageerib paarilisele, küsib vastu ja jõuab ühise otsuseni."}},
  "a2b1-080": {"canDo":"Ma lahendan B1 eksami vormis lugemise, kuulamise, kirjutamise ja rääkimise ülesanded; kokku vähemalt 70% ning kirjutamises ja rääkimises vähemalt 65%.","goals":{"g_vocab":"Õpilane kasutab mooduli arvamuse, võrdlemise ja põhjendamise sõnavara eksamiülesannetes ilma toeta.","g_read":"Õpilane lahendab B1 lugemise ja kuulamise ülesanded (kuulutused, 250–300-sõnaline artikkel, lünktekstid, teated, intervjuu) vähemalt 70% ulatuses.","g_notice":"Õpilane kasutab õigesti mooduli grammatikat: sõnajärg pärast „minu arvates”, keskvõrre, kuna/seetõttu, des-vorm, umbisikuline ja tingiv vorm, kaudne kõne.","g_use":"Õpilane kirjutab 50-sõnalise teate ja 100–130-sõnalise arvamuskirja, räägib 2 minutit teemakaardi järgi ja jõuab paarilisega kokkuleppele; kirjutamises ja rääkimises vähemalt 65%."}},
  "a2b1-081": {"canDo":"Ma leian teadetest, kuulutustest ja 200–250-sõnalisest artiklist vajaliku info ning vastan õigesti vähemalt 75% küsimustest.","goals":{"g_vocab":"Õpilane mõistab teadete ja kuulutuste sõnu: avatud, suletud, remondi tõttu, tasuta, soodustus, kehtib, registreeruge ette.","g_read":"Õpilane seob 9 olukorda 6 kuulutusega ja leiab 200–250-sõnalisest artiklist või ühistu kirjast fakti, tähtaja ja peamõtte.","g_notice":"Õpilane mõistab ja moodustab teadete umbisikulisi vorme: suletakse, müüakse, remonditi, ei suitsetata, lapsi oodatakse.","g_use":"Õpilane selgitab teise inimese jaoks, mis teates on kirjas ja mida tuleb teha, ning kirjutab ise lühikese teate."}},
  "a2b1-082": {"canDo":"Ma kirjutan 50-sõnalise teate nelja punktiga, täidan 10 küsimusega ankeedi ja kirjutan 100–130-sõnalise e-kirja, mis katab kõik punktid.","goals":{"g_vocab":"Õpilane kasutab kirja fraase: Lugupeetud…, Kirjutan teile seoses…, Kas oleks võimalik…, Ette tänades, Lugupidamisega.","g_read":"Õpilane leiab näidiskirjast, ankeedist ja häälsõnumist kõik ülesande punktid ning märkab, kui mõni puudub.","g_notice":"Õpilane palub viisakalt tingiva kõneviisiga (sooviksin, kas saaksite) ja edastab teise sõnu et- ja kas-lausega.","g_use":"Õpilane kirjutab 50-sõnalise teate nelja punktiga, täidab 10 küsimusega ankeedi põhjendustega ja kirjutab 100–130-sõnalise e-kirja."}},
  "a2b1-083": {"canDo":"Ma kirjutan 110–140-sõnalise arvamusteksti, kus on seisukoht, kaks põhjust, näide ja kokkuvõte.","goals":{"g_vocab":"Õpilane kasutab arvamusteksti sidesõnu: minu arvates, esiteks, teiseks, näiteks, muidugi, teisalt, kokkuvõttes.","g_read":"Õpilane leiab arvamustekstist ja foorumist seisukoha, põhjused, näite, vastuargumendi ja kokkuvõtte.","g_notice":"Õpilane seob mõtted kuigi-lausega (ilma „aga”-ta), sest-lausega ja des-vormiga (kodus töötades, bussiga sõites).","g_use":"Õpilane kirjutab 110–140-sõnalise arvamusteksti ning 100-sõnalise loo või isikliku kirja ja jõuab paaris kokkuleppele."}},
  "a2b1-084": {"canDo":"Ma kirjeldan tabelit, sõiduplaani või küsitlust: sõnastan vähemalt viis fakti, kaks võrdlust ja ühe järelduse.","goals":{"g_vocab":"Õpilane kasutab andmete sõnu: kõige rohkem, rohkem kui, vähem kui, umbes, peaaegu, enamik, pooled, kolmandik.","g_read":"Õpilane loeb tabelist, sõiduplaanist, aruandest ja raadiouudisest arvud ning võrdleb neid.","g_notice":"Õpilane kasutab mitmuse käändeid ja ühildumist (enamik vastajatest sõidab, pooled sõidavad) ning umbisikulist minevikku (küsitleti).","g_use":"Õpilane sõnastab tabeli põhjal vähemalt viis fakti, kaks võrdlust ja ühe järelduse suuliselt ja kirjalikult."}},
  "a2b1-085": {"canDo":"Ma lahendan Harno B1 lugemise neli ülesannet ning kirjutan teate või ankeedi ja isikliku kirja või loo; tulemus vähemalt 70%.","goals":{"g_vocab":"Õpilane mõistab kuulutuste, kirjade, arvamuste ja andmete sõnavara ning kasutab kirja fraase ilma toeta.","g_read":"Õpilane lahendab Harno B1 lugemise neli ülesannet: olukord ↔ kuulutus, valikvastused, valikulüngad ja lauseosade pank.","g_notice":"Õpilane valib õige vormi ja sidesõna: umbisikuline tegumood, tingiv kõneviis, kaudne kõne, des-vorm, enamik + mitmus.","g_use":"Õpilane täidab ankeedi või kirjutab 50-sõnalise teate ning kirjutab 100-sõnalise isikliku kirja või loo."}},
  "a2b1-086": {"canDo":"Ma räägin tuttaval teemal 3–4 minutit märksõnaplaani järgi: algus, kaks-kolm mõtet näidetega ja kokkuvõte.","goals":{"g_vocab":"Õpilane kasutab monoloogi siduvaid väljendeid: kõigepealt, esiteks, näiteks, seetõttu, teisest küljest, kokkuvõtteks.","g_read":"Õpilane leiab monoloogist ja 2–3-minutilisest raadiomonoloogist peamõtte, põhjused ja näited (Harno kuulamine 2, kuus valikküsimust).","g_notice":"Õpilane kasutab monoloogis des-vormi ja umbisikulist olevikku: Tööle sõites kuulan…; Meie peres tehakse…","g_use":"Õpilane peab märksõnaplaani järgi 3–4-minutilise monoloogi, vastab kuulajate küsimustele ja lühendab loo kahe minuti peale."}},
  "a2b1-087": {"canDo":"Ma hoian 5-minutilist vestlust käigus: esitan vähemalt kolm täpsustavat või vastuküsimust, reageerin ja ütlen viisakalt, kas olen nõus.","goals":{"g_vocab":"Õpilane kasutab vestluse väljendeid: Kas ma sain õigesti aru, et…?, Aga sina?, Tõesti?, Ma ei ole päris nõus, sest…","g_read":"Õpilane mõistab lühiteateid ja intervjuud (Harno kuulamine 1 ja 4) ning leiab ideekaardist ja artiklist vajaliku info.","g_notice":"Õpilane moodustab kaudse küsimuse ja kaudse kõne (Ta küsis, kas…; Ta ütles, et…) ning viisaka tingiva küsimuse (Kas te võiksite…?).","g_use":"Õpilane peab 5-minutilise dialoogi, esitab vähemalt kolm küsimust, jõuab ideekaardi abil kokkuleppele ja helistab kaartide järgi."}},
  "a2b1-088": {"canDo":"Ma lahendan teeninduses, transpordis, koolis või tööl tekkinud probleemi: selgitan, täpsustan, pakun kaks varianti ja jõuan lahenduseni ka siis, kui tingimus muutub.","goals":{"g_vocab":"Õpilane kasutab probleemi lahendamise väljendeid: Mul on probleem…, Kas oleks võimalik…?, Teine variant oleks…, Mis siis, kui…?, Lepime kokku, et…","g_read":"Õpilane leiab kaebusest, tingimustest ja telefonikõnest probleemi, põhjuse ja lahenduse ning vastab 1–2 sõnaga (Harno kuulamine 3).","g_notice":"Õpilane kasutab umbisikulist minevikku ja tingiva kõneviisi minevikku: Pakk saadeti valele aadressile; Kui mulle oleks öeldud, oleksin…","g_use":"Õpilane lahendab rollimängus kaks probleemi lõpuni ka siis, kui tingimus muutub, ja kirjutab omanikule umbes 100-sõnalise kirja."}},
  "a2b1-089": {"canDo": "Ma sooritan Harno B1 eksami vormis proovitöö kõigis neljas osaoskuses ajapiiri sees ja saan kokku vähemalt 70%.", "goals": {"g_read": "Õpilane lahendab ajapiiri sees Harno B1 kuulamise neli osa (30 punkti) ja lugemise neli osa (33 punkti).", "g_notice": "Õpilane valib valiklünktekstis ja keeleosas õige vormi: umbisikuline tegumood, tingiv kõneviis, kaudne kõne, des-vorm, rektsioon.", "g_use": "Õpilane kirjutab 50-sõnalise teate ja 100-sõnalise isikliku kirja ning lahendab rääkimise osad 1a, 1b ja 2."}},
  "a2b1-090": {"canDo": "Ma näitan B1 taset kõigis neljas osaoskuses: saan igas osas vähemalt 60% ja kokku vähemalt 70% ning tean oma järgmised eesmärgid.", "goals": {"g_read": "Õpilane saab teises proovieksamis kuulamises vähemalt 18/30 ja lugemises vähemalt 20/33 punkti (60%).", "g_notice": "Õpilane kasutab kirjutades ja rääkides piisavalt täpselt B1 grammatikat: umbisikuline tegumood, tingiv kõneviis, kaudne kõne, des-vorm.", "g_use": "Õpilane kirjutab teate ja loo, lahendab rääkimise osad nõutud ajas ning koostab tulemuste põhjal oma B1 → B2 eesmärkide kaardi."}},
};
